<script setup lang="ts">
import { computed, defineAsyncComponent, reactive, ref, watch } from 'vue'
import AppIcon from '../components/AppIcon.vue'
import DentalCanvas from './DentalCanvas.vue'
import DentalResearch from './DentalResearch.vue'
import catalog from '../../../contracts/dental/sources.v1.json'
import { chartRows, dentalAdvice, newPainRecord, safetySigns, toothById, toothLabel, type Appliance, type DentalMode, type DentalView, type PainRecord } from './model'
import './dental.css'
import './caseStudio.css'
const DentalCaseStudio=defineAsyncComponent(()=>import('./DentalCaseStudio.vue'))
const props=withDefaults(defineProps<{initialMode:DentalMode;reducedMotion:boolean;user?:{id:number;email:string}|null;authPending?:boolean;authError?:string}>(),{user:null,authPending:false,authError:''})
const emit=defineEmits<{mode:[value:DentalMode];close:[];authenticate:[email:string,password:string,register:boolean]}>()
const casesOpened=ref(props.initialMode==='cases')
const mode=ref<DentalMode>(props.initialMode),selected=ref(11),view=ref<DentalView>('front'),appliance=ref<Appliance>(props.initialMode==='braces'?'metal':'none'),elastic=ref('#399d91'),opening=ref(.14),structure=ref('enamel')
const canvas=ref<InstanceType<typeof DentalCanvas>>(),canvasKey=ref(0),canvasError=ref(''),researchOpened=ref(props.initialMode==='research'),notice=ref('')
const records=reactive<Record<number,PainRecord>>({11:newPainRecord()}),priorEmergency=ref(false),emergencyReportedAt=ref<string|null>(null),startedAt=ref(new Date().toISOString())
const tooth=computed(()=>toothById(selected.value)!)
const record=computed(()=>records[selected.value]??(records[selected.value]=newPainRecord(selected.value)))
const advice=computed(()=>dentalAdvice(record.value,priorEmergency.value))
const sourceLinks=computed(()=>catalog.sources.filter(s=>advice.value.sources.includes(s.id)))
const topicSource=(id:string)=>catalog.sources.find(s=>s.id===id)!
const reportedTeeth=computed(()=>Object.values(records).filter(r=>r.severity>0||r.reviewed||r.signs.length>0||r.infectionSigns||r.applianceIssue!=='none'))
const layers=[{id:'enamel',label:'Enamel',color:'#e6d9bd',description:'The hard outer crown surface. It covers the visible part of the tooth.'},{id:'dentin',label:'Dentin',color:'#c6a45c',description:'The tissue beneath enamel and around the root canal. Exposed dentin can be associated with sensitivity.'},{id:'pulp',label:'Pulp & canals',color:'#c5646f',description:'The central soft tissue contains nerves and blood vessels. The diagram shows a simplified canal path.'},{id:'root',label:'Tooth roots',color:'#b8a98d',description:'Roots anchor the tooth below the gum line. Root shapes and counts vary between people.'}]
const currentLayer=computed(()=>layers.find(l=>l.id===structure.value)!)
watch(()=>props.initialMode,value=>{mode.value=value})
watch(mode,value=>{if(value==='braces'&&appliance.value==='none')appliance.value='metal';if(value==='research')researchOpened.value=true;if(value==='cases')casesOpened.value=true;emit('mode',value)})
watch(records,()=>{if(Object.values(records).some(r=>safetySigns.some(s=>s.emergency&&r.signs.includes(s.id)))){priorEmergency.value=true;emergencyReportedAt.value??=new Date().toISOString()}},{deep:true,flush:'sync'})
function choose(id:number){selected.value=id;if(!records[id])records[id]=newPainRecord(id);notice.value=''}
function chartKey(event:KeyboardEvent,rowIndex:number,index:number){let nextRow=rowIndex,next=index;if(event.key==='ArrowRight')next=Math.min(15,index+1);else if(event.key==='ArrowLeft')next=Math.max(0,index-1);else if(event.key==='ArrowUp')nextRow=0;else if(event.key==='ArrowDown')nextRow=1;else if(event.key==='Home')next=0;else if(event.key==='End')next=15;else return;event.preventDefault();const id=chartRows[nextRow]![next]!;choose(id);(event.currentTarget as HTMLElement).closest('.dental-tooth-chart')?.querySelector<HTMLButtonElement>(`[data-fdi="${id}"]`)?.focus()}
function resetPain(){for(const key of Object.keys(records))delete records[Number(key)];records[selected.value]=newPainRecord(selected.value);priorEmergency.value=false;emergencyReportedAt.value=null;startedAt.value=new Date().toISOString();notice.value='A new dental pain assessment has started.'}
function exportAssessment(){const text=JSON.stringify({schema_version:1,module:'dental-research',clinical_validation:false,started_at:startedAt.value,exported_at:new Date().toISOString(),notation:'FDI permanent dentition; patient perspective',selected_tooth:selected.value,records:reportedTeeth.value,emergency_reported_at:emergencyReportedAt.value,current_guidance:advice.value,appliance_visualization:{type:appliance.value,elastic_color:elastic.value,geometry:'original dimensionless teaching atlas; not an appliance prescription'},sources:catalog.sources},null,2),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download='humantwin-dental-assessment.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notice.value='Dental research summary exported.'}
</script>
<template>
 <section class="dental-workspace" aria-label="Dental and orthodontic workspace">
  <div class="dental-introduction"><div class="dental-intro-icon"><AppIcon name="tooth" :size="30"/></div><div><span class="dental-eyebrow">ORAL HEALTH · ANATOMY · ORTHODONTICS</span><p>Explore the tooth. Understand the context. Follow the evidence.</p></div><span class="dental-reference-tag"><i/>Research workspace</span></div>
  <div class="dental-workspace-bar"><div class="dental-mode-tabs" role="group" aria-label="Dental workspace mode"><button :aria-pressed="mode==='pain'" @click="mode='pain'"><AppIcon name="tooth" :size="18"/>Teeth & pain</button><button :aria-pressed="mode==='braces'" @click="mode='braces'"><AppIcon name="braces" :size="18"/>Braces studio</button><button :aria-pressed="mode==='cases'" @click="mode='cases'"><AppIcon name="tooth" :size="18"/>Cases & practice</button><button :aria-pressed="mode==='research'" @click="mode='research'"><AppIcon name="layers" :size="18"/>Research data</button></div><button class="dental-text-button dental-back" @click="emit('close')"><AppIcon name="arrowLeft" :size="15"/>Body explorer</button></div>
  <div v-if="priorEmergency&&mode!=='pain'" class="dental-advice emergency" role="alert"><AppIcon name="error"/><div><strong>Emergency symptoms were reported</strong><p>Contact local emergency services or an emergency department now. Changing tabs does not clear this guidance.</p></div></div>
  <div v-if="mode==='pain'||mode==='braces'" class="dental-case-launch"><div><h3>Bring a patient case into the picture.</h3><p>Local photos, bite examples, individual tooth exploration and student tests.</p></div><button class="button-secondary" @click="mode='cases'">Open cases & practice <AppIcon name="arrowRight" :size="15"/></button></div>
  <DentalCaseStudio v-if="casesOpened" v-show="mode==='cases'" :reduced-motion="reducedMotion" :user="user" :auth-pending="authPending" :auth-error="authError" @authenticate="(email,password,register)=>emit('authenticate',email,password,register)"/>
  <div v-if="mode==='pain'||mode==='braces'" class="dental-workbench">
   <div class="dental-model-column"><section class="dental-atlas panel" aria-label="Tooth atlas"><div class="dental-atlas-heading"><div><span class="dental-eyebrow">{{ mode==='braces'?'APPLIANCE VISUALIZATION':'PERMANENT DENTITION' }}</span><h2>{{ mode==='braces'?'A closer look at braces.':'Meet your dental anatomy.' }}</h2></div><span class="dental-counter">32 <small>teeth</small></span></div>
    <div class="dental-views" role="group" aria-label="Dental model view"><button v-for="v in (['front','upper','lower','side','section'] as const)" :key="v" :aria-pressed="view===v" @click="view=v;canvasError=''">{{ ({front:'Front',upper:'Upper arch',lower:'Lower arch',side:'Side',section:'Tooth section'})[v] }}</button></div>
    <div class="dental-model-stage"><DentalCanvas :key="canvasKey" ref="canvas" :view="view" :selected="selected" :structure="view==='section'?structure:'all'" :appliance="appliance" :elastic="elastic" :opening="opening" :reduced-motion="reducedMotion" :scan="null" @select="choose" @error="canvasError=$event"/><div class="dental-canvas-badge">3D TOOTH ATLAS <span>{{ view==='section'?'Enamel · dentin · pulp · roots':'Original educational geometry' }}</span></div><div class="dental-stage-label"><span>SELECTED TOOTH</span><strong>{{ selected }}</strong><small>{{ tooth.jaw }} {{ tooth.side }} · patient perspective</small></div><div v-if="canvasError" class="dental-canvas-error" role="alert"><strong>3D viewer unavailable</strong><p>{{ canvasError }}</p><button class="button-secondary" @click="canvasKey++;canvasError=''">Retry viewer</button><span>The numbered tooth chart still works.</span></div></div>
    <div class="dental-atlas-footer"><span><AppIcon name="mouse" :size="15"/>Drag to orbit · scroll to zoom</span><div><button aria-label="Zoom dental model in" @click="canvas?.zoom(1)"><AppIcon name="plus" :size="16"/></button><button aria-label="Zoom dental model out" @click="canvas?.zoom(-1)"><AppIcon name="minus" :size="16"/></button><button aria-label="Reset dental model" @click="canvas?.reset()"><AppIcon name="reset" :size="16"/></button></div></div>
    <div class="dental-tooth-chart"><div class="dental-chart-heading"><strong>Select a tooth</strong><span>FDI notation · patient’s right is on your left</span></div><div class="dental-chart-row" v-for="(row,ri) in chartRows" :key="ri"><span class="dental-arch-name">{{ ri===0?'UPPER JAW':'LOWER JAW' }}</span><div role="group" :aria-label="ri===0?'Upper teeth':'Lower teeth'"><button v-for="(id,i) in row" :key="id" :data-fdi="id" :class="{'is-selected':selected===id,'has-pain':(records[id]?.severity??0)>0,'dental-midline':i===8}" :aria-pressed="selected===id" :aria-label="toothLabel(id)" :title="toothLabel(id)" @click="choose(id)" @keydown="chartKey($event,ri,i)"><AppIcon name="tooth" :size="21"/><span>{{ id }}</span><i v-if="(records[id]?.severity??0)>0"/></button></div></div></div>
   </section>
   <section v-if="mode==='pain'" class="dental-layers panel"><div><span class="dental-eyebrow">INSIDE THE TOOTH</span><h3>Four layers. One connected structure.</h3></div><div class="dental-layer-options"><button v-for="l in layers" :key="l.id" :aria-pressed="structure===l.id&&view==='section'" @click="structure=l.id;view='section'"><i :style="{background:l.color}"/>{{ l.label }}</button></div><p>{{ currentLayer.description }}</p><span class="dental-small">Simplified permanent-tooth anatomy. Shapes and root counts vary; this is not a scan of the selected subject.</span></section>
   <section v-else class="dental-brace-guide panel"><AppIcon name="info" :size="21"/><div><h3>Understand the hardware.</h3><p>Brackets hold the archwire, and ligatures retain the wire. Tooth movement needs a clinician’s planned forces and monitoring. This view illustrates components and appearance.</p><a href="https://aaoinfo.org/whats-trending/what-is-an-orthodontic-emergency/" target="_blank" rel="noopener noreferrer">Appliance care · American Association of Orthodontists ↗</a></div></section>
   <section class="dental-learning panel"><span class="dental-eyebrow">SOURCE-LINKED LEARNING</span><h3>Common concerns, explained.</h3><p>Educational topics to discuss with your dental team.</p><div><details v-for="topic in catalog.learning" :key="topic.title"><summary>{{ topic.title }}<AppIcon name="plus" :size="14"/></summary><p>{{ topic.text }}</p><a :href="topicSource(topic.source).url" target="_blank" rel="noopener noreferrer">{{ topicSource(topic.source).title }} &#8599;</a></details></div></section><div class="dental-research-invitation"><AppIcon name="layers" :size="24"/><div><strong>Your scans. Your measurements. One research space.</strong><p>Inspect real casts and X-rays, or compare coded observations over time.</p></div><button class="dental-text-button" @click="mode='research'">Open research data<AppIcon name="arrowRight" :size="16"/></button></div>
   </div>
   <aside class="dental-context-column" aria-label="Dental details and assessment">
    <section class="dental-tooth-card panel"><span class="dental-eyebrow">TOOTH IN FOCUS</span><div class="dental-tooth-title"><div class="dental-fdi">{{ selected }}</div><div><h3>{{ tooth.name }}</h3><p>{{ tooth.jaw==='upper'?'Maxillary':'Mandibular' }} · patient’s {{ tooth.side }}</p></div></div><p>{{ tooth.purpose }}</p><div class="dental-tooth-facts"><span><i/>Permanent tooth</span><span>FDI {{ selected }}</span></div></section>
    <template v-if="mode==='pain'"><section class="dental-pain-card panel"><div class="dental-card-heading"><div><span class="dental-eyebrow">TOOTH-SPECIFIC INTAKE</span><h3>Tell us what you feel.</h3></div><AppIcon name="chat" :size="21"/></div><label class="dental-pain-scale" :for="`dental-pain-${selected}`"><span>Pain intensity <strong>{{ record.severity }}<small>/10</small></strong></span><input :id="`dental-pain-${selected}`" v-model.number="record.severity" type="range" min="0" max="10" step="1" aria-label="Dental pain intensity"/><span class="dental-scale-labels"><small>No pain</small><small>Worst pain</small></span></label><label class="dental-field">When did it start?<select v-model="record.duration" aria-label="Dental pain duration"><option value="today">Today / less than two days</option><option value="days">More than two days</option><option value="weeks">A week or longer</option></select></label><label class="dental-field">What brings it on?<select v-model="record.trigger" aria-label="Dental pain trigger"><option value="unsure">Not sure yet</option><option value="cold">Cold food or drink</option><option value="heat">Hot food or drink</option><option value="bite">Biting or chewing</option><option value="brushing">Brushing / touching the gum</option><option value="spontaneous">No obvious trigger</option><option value="adjustment">After a braces adjustment</option></select></label><label class="dental-field">Any appliance issue?<select v-model="record.applianceIssue" aria-label="Dental appliance issue"><option value="none">None / no appliance</option><option value="wire">Rubbing or poking wire</option><option value="bracket">Loose or broken bracket</option><option value="aligner">Lost / damaged aligner or retainer</option><option value="soreness">Soreness after an adjustment</option></select></label><label class="dental-check dental-infection-check"><input v-model="record.infectionSigns" type="checkbox"/>Fever, cheek/jaw swelling or a bad taste</label></section>
    <section class="dental-safety-card panel"><div class="dental-card-heading"><div><span class="dental-eyebrow">BEFORE ANY NEXT STEP</span><h3>Check these signs.</h3></div><AppIcon name="shield" :size="22"/></div><p>Select any that apply.</p><label class="dental-check" v-for="sign in safetySigns" :key="sign.id"><input v-model="record.signs" type="checkbox" :value="sign.id"/>{{ sign.label }}</label><label class="dental-check dental-review-check"><input v-model="record.reviewed" type="checkbox"/>I have reviewed every sign above.</label></section>
    <section class="dental-advice" :class="advice.level" :role="advice.level==='emergency'?'alert':'status'" data-testid="dental-guidance"><span class="dental-eyebrow">{{ advice.level==='incomplete'?'SAFETY SCREEN INCOMPLETE':'SUGGESTED NEXT STEP' }}</span><h3>{{ advice.title }}</h3><p>{{ advice.detail }}</p><ul v-if="advice.actions.length"><li v-for="action in advice.actions" :key="action">{{ action }}</li></ul><div class="dental-guidance-sources"><a v-for="source in sourceLinks" :key="source.id" :href="source.url" target="_blank" rel="noopener noreferrer">{{ source.title }} ↗</a></div></section></template>
    <template v-else><section class="dental-braces-card panel"><span class="dental-eyebrow">DESIGN THE REFERENCE VIEW</span><h3>Choose your appliance.</h3><p class="dental-small">Appearance controls for the teaching atlas.</p><div class="dental-appliance-options"><button v-for="a in (['metal','ceramic','none'] as const)" :key="a" :aria-pressed="appliance===a" @click="appliance=a"><span class="dental-bracket-swatch" :class="a"><i/><i/><i/><i/></span><strong>{{ ({metal:'Metal brackets',ceramic:'Ceramic brackets',none:'Natural dentition'})[a] }}</strong><AppIcon v-if="appliance===a" name="check" :size="17"/></button></div><span class="dental-field-label">Ligature color</span><div class="dental-elastics"><button v-for="c in [{color:'#399d91',name:'Mint'},{color:'#8e7ab5',name:'Lavender'},{color:'#d48c83',name:'Coral'},{color:'#4d638c',name:'Navy'},{color:'#adb9bc',name:'Silver'}]" :key="c.color" :style="{'--elastic':c.color}" :aria-label="`${c.name} ligatures`" :aria-pressed="elastic===c.color" @click="elastic=c.color"><AppIcon v-if="elastic===c.color" name="check" :size="14"/></button></div><label class="dental-field dental-opening">Jaw separation<input v-model.number="opening" type="range" min="0" max="0.8" step="0.02" aria-label="Jaw separation"/><span class="dental-small">Explore the arches; this slider changes only the display.</span></label></section><section class="dental-appliance-help panel"><span class="dental-eyebrow">BETWEEN APPOINTMENTS</span><h3>Something doesn’t feel right?</h3><p>Record the affected tooth, pain and appliance issue. Your orthodontist can decide what needs attention.</p><button class="button-secondary" @click="mode='pain'">Check tooth or braces pain<AppIcon name="arrowRight" :size="16"/></button><a href="https://www.nhsfife.org/services/all-services/patient-advice/orthodontic-emergencies/" target="_blank" rel="noopener noreferrer">NHS orthodontic care guidance ↗</a></section></template>
   </aside>
  </div>
  <DentalResearch v-if="researchOpened" v-show="mode==='research'" :reduced-motion="reducedMotion"/>
  <div class="dental-session-footer"><div><AppIcon name="shield" :size="17"/><span>Session only · no automatic saving or upload<br/><small>Educational research prototype. A dentist or orthodontist must assess symptoms and plan treatment.</small></span></div><div><button class="dental-text-button" @click="resetPain">New pain assessment</button><button class="button-secondary" :disabled="!reportedTeeth.length" @click="exportAssessment"><AppIcon name="download" :size="16"/>Export summary</button></div></div><p v-if="notice" class="dental-notice" role="status">{{ notice }}</p>
 </section>
</template>
